let benchmarkRunning = false;
        let abortController = null;
        let selectedPayloadMB = 64;
        let customDirHandle = null;

        // Results state
        let lastResult = {
            seqWrite: 0,
            seqWritePeak: 0,
            seqRead: 0,
            seqReadPeak: 0,
            iopsWrite: 0,
            latencyWrite: 0,
            iopsRead: 0,
            latencyRead: 0,
            tier: 'Unknown',
            payloadMB: 64,
            timestamp: null
        };

        const graphHistory = [];
        const canvas = document.getElementById('throughputGraph');
        const ctx = canvas ? canvas.getContext('2d') : null;

        document.addEventListener('DOMContentLoaded', () => {
            initStorageInfo();
            drawEmptyGraph();
        });

        async function initStorageInfo() {
            if ('storage' in navigator && 'estimate' in navigator.storage) {
                try {
                    const estimate = await navigator.storage.estimate();
                    const quotaGB = (estimate.quota / (1024 ** 3)).toFixed(1);
                    const usageGB = (estimate.usage / (1024 ** 3)).toFixed(2);
                    const freeGB = ((estimate.quota - estimate.usage) / (1024 ** 3)).toFixed(1);

                    const totalEl = document.getElementById('quota-total-val');
                    const freeEl = document.getElementById('quota-free-val');
                    if (totalEl) totalEl.innerText = `${quotaGB} GB`;
                    if (freeEl) freeEl.innerText = `${freeGB} GB Free`;
                } catch (e) {
                    console.warn("Storage estimate not accessible:", e);
                }
            } else {
                const totalEl = document.getElementById('quota-total-val');
                if (totalEl) totalEl.innerText = "N/A";
            }
        }

        function setPayloadSize(sizeMB, btn) {
            if (benchmarkRunning) return;
            selectedPayloadMB = sizeMB;
            document.querySelectorAll('.payload-btn').forEach(b => {
                b.className = "payload-btn py-2.5 px-3 rounded-xl border border-slate-200 text-xs font-bold text-slate-700 hover:border-sky-500 transition text-center select-none";
            });
            btn.className = "payload-btn active-payload py-2.5 px-3 rounded-xl border-2 border-sky-600 bg-sky-50 text-xs font-black text-sky-800 transition text-center select-none";
        }

        async function pickCustomDirectory() {
            if (benchmarkRunning) return;
            if ('showDirectoryPicker' in window) {
                try {
                    customDirHandle = await window.showDirectoryPicker({ mode: 'readwrite' });
                    const label = document.getElementById('target-drive-label');
                    if (label) label.innerText = `Target: ${customDirHandle.name.substring(0, 16)}`;
                    const badge = document.getElementById('api-status-badge');
                    if (badge) {
                        badge.innerText = "Direct Disk Access";
                        badge.className = "bg-sky-100 text-sky-800 px-2.5 py-0.5 rounded-md font-bold text-xs uppercase tracking-wider";
                    }
                } catch (e) {
                    if (e.name !== 'AbortError') {
                        console.warn("Directory selection notice:", e);
                    }
                }
            } else {
                alert("Direct directory selection is supported on desktop Chromium browsers. Testing will proceed using high-speed Origin Private File System (OPFS).");
            }
        }

        async function getBenchmarkDirectory() {
            if (customDirHandle) {
                return customDirHandle;
            }
            if (navigator.storage && navigator.storage.getDirectory) {
                return await navigator.storage.getDirectory();
            }
            throw new Error("Modern FileSystem API is not supported in this browser.");
        }

        function updateProgress(stageText, percent) {
            const stageEl = document.getElementById('current-stage-label');
            const percentEl = document.getElementById('progress-percent');
            const fillEl = document.getElementById('progress-fill');
            const engineStatus = document.getElementById('engine-status-val');

            if (stageEl) stageEl.innerText = stageText;
            if (percentEl) percentEl.innerText = `${Math.min(100, Math.round(percent))}%`;
            if (fillEl) fillEl.style.width = `${Math.min(100, Math.round(percent))}%`;
            if (engineStatus) engineStatus.innerText = "BENCHMARKING";
        }

        function addGraphPoint(speedMBs) {
            graphHistory.push(speedMBs);
            if (graphHistory.length > 50) graphHistory.shift();
            drawGraph();
        }

        function drawEmptyGraph() {
            if (!ctx || !canvas) return;
            const w = canvas.width;
            const h = canvas.height;
            ctx.clearRect(0, 0, w, h);
            ctx.fillStyle = '#020617';
            ctx.fillRect(0, 0, w, h);

            // Subtle grid lines
            ctx.strokeStyle = '#1e293b';
            ctx.lineWidth = 1;
            for (let y = 30; y < h; y += 35) {
                ctx.beginPath();
                ctx.moveTo(0, y);
                ctx.lineTo(w, y);
                ctx.stroke();
            }

            ctx.fillStyle = '#475569';
            ctx.font = '600 12px Inter, sans-serif';
            ctx.textAlign = 'center';
            ctx.fillText('Live Throughput Graph (MB/s)', w / 2, h / 2);
        }

        function drawGraph() {
            if (!ctx || !canvas || graphHistory.length === 0) return;
            const w = canvas.width;
            const h = canvas.height;
            ctx.clearRect(0, 0, w, h);
            ctx.fillStyle = '#020617';
            ctx.fillRect(0, 0, w, h);

            // Grid
            ctx.strokeStyle = '#1e293b';
            ctx.lineWidth = 1;
            for (let y = 25; y < h; y += 35) {
                ctx.beginPath();
                ctx.moveTo(0, y);
                ctx.lineTo(w, y);
                ctx.stroke();
            }

            const maxSpeed = Math.max(...graphHistory, 200) * 1.15;
            const stepX = w / (graphHistory.length - 1 || 1);

            // Gradient fill under curve
            const grad = ctx.createLinearGradient(0, 0, 0, h);
            grad.addColorStop(0, 'rgba(14, 165, 233, 0.45)');
            grad.addColorStop(1, 'rgba(14, 165, 233, 0.0)');

            ctx.beginPath();
            ctx.moveTo(0, h);
            graphHistory.forEach((val, i) => {
                const x = i * stepX;
                const y = h - (val / maxSpeed) * (h - 20) - 5;
                if (i === 0) ctx.lineTo(x, y);
                else ctx.lineTo(x, y);
            });
            ctx.lineTo(w, h);
            ctx.fillStyle = grad;
            ctx.fill();

            // Line curve
            ctx.beginPath();
            graphHistory.forEach((val, i) => {
                const x = i * stepX;
                const y = h - (val / maxSpeed) * (h - 20) - 5;
                if (i === 0) ctx.moveTo(x, y);
                else ctx.lineTo(x, y);
            });
            ctx.strokeStyle = '#38bdf8';
            ctx.lineWidth = 2.5;
            ctx.stroke();

            // Peak indicator
            const current = graphHistory[graphHistory.length - 1];
            ctx.fillStyle = '#38bdf8';
            ctx.font = 'bold 11px JetBrains Mono, monospace';
            ctx.textAlign = 'right';
            ctx.fillText(`${current.toFixed(1)} MB/s`, w - 12, 22);
        }

        async function startBenchmark() {
            if (benchmarkRunning) return;
            benchmarkRunning = true;
            abortController = new AbortController();

            const runBtn = document.getElementById('btn-run-benchmark');
            const cancelBtn = document.getElementById('btn-cancel-benchmark');
            const runText = document.getElementById('run-btn-text');

            if (runBtn) {
                runBtn.classList.add('opacity-50', 'pointer-events-none');
            }
            if (cancelBtn) cancelBtn.classList.remove('hidden');
            if (runText) runText.innerText = "Benchmarking...";

            graphHistory.length = 0;
            resetDisplays();

            const fileName = `toolkitgen_bench_${Date.now()}.bin`;
            let rootDir = null;
            let fileHandle = null;

            try {
                rootDir = await getBenchmarkDirectory();
                fileHandle = await rootDir.getFileHandle(fileName, { create: true });

                const totalBytes = selectedPayloadMB * 1024 * 1024;
                const chunkSize = 1024 * 1024; // 1MB chunks for sequential
                const numChunks = Math.floor(totalBytes / chunkSize);

                // High-entropy buffer creation
                const chunkData = new Uint8Array(chunkSize);
                for (let i = 0; i < chunkSize; i += 4) {
                    chunkData[i] = (i * 1664525 + 1013904223) & 0xFF;
                    chunkData[i + 1] = (i >> 8) & 0xFF;
                    chunkData[i + 2] = (i >> 16) & 0xFF;
                    chunkData[i + 3] = (i * 31) & 0xFF;
                }

                // ==========================================
                // STAGE 1: Sequential Write
                // ==========================================
                updateProgress("Sequential Write (MB/s)...", 10);
                const writable = await fileHandle.createWritable();
                const writeStart = performance.now();
                let bytesWritten = 0;
                let peakWrite = 0;

                for (let c = 0; c < numChunks; c++) {
                    if (abortController.signal.aborted) throw new Error("Benchmark Aborted");
                    const chunkStart = performance.now();
                    await writable.write(chunkData);
                    bytesWritten += chunkSize;
                    const chunkElapsedSec = (performance.now() - chunkStart) / 1000;
                    const chunkSpeedMBs = (chunkSize / (1024 * 1024)) / Math.max(chunkElapsedSec, 0.0001);

                    if (chunkSpeedMBs > peakWrite) peakWrite = chunkSpeedMBs;
                    addGraphPoint(chunkSpeedMBs);

                    const currentAvgMBs = (bytesWritten / (1024 * 1024)) / ((performance.now() - writeStart) / 1000);
                    setVal('seq-write-val', currentAvgMBs.toFixed(1));
                    setVal('seq-write-peak', `${peakWrite.toFixed(1)} MB/s`);
                    updateProgress(`Sequential Write: ${bytesWritten / (1024 * 1024)}MB / ${selectedPayloadMB}MB`, 10 + (c / numChunks) * 35);
                }
                await writable.close();
                const totalWriteElapsed = (performance.now() - writeStart) / 1000;
                const finalWriteMBs = (totalBytes / (1024 * 1024)) / Math.max(totalWriteElapsed, 0.001);
                lastResult.seqWrite = finalWriteMBs;
                lastResult.seqWritePeak = peakWrite;
                setVal('seq-write-val', finalWriteMBs.toFixed(1));

                // Short thermal recovery pause
                await new Promise(r => setTimeout(r, 400));

                // ==========================================
                // STAGE 2: Sequential Read
                // ==========================================
                updateProgress("Sequential Read (MB/s)...", 50);
                const file = await fileHandle.getFile();
                const readStart = performance.now();
                let bytesRead = 0;
                let peakRead = 0;

                for (let offset = 0; offset < totalBytes; offset += chunkSize) {
                    if (abortController.signal.aborted) throw new Error("Benchmark Aborted");
                    const sliceStart = performance.now();
                    const slice = file.slice(offset, offset + chunkSize);
                    await slice.arrayBuffer();
                    bytesRead += chunkSize;

                    const sliceElapsed = (performance.now() - sliceStart) / 1000;
                    const sliceSpeedMBs = (chunkSize / (1024 * 1024)) / Math.max(sliceElapsed, 0.0001);
                    if (sliceSpeedMBs > peakRead) peakRead = sliceSpeedMBs;
                    addGraphPoint(sliceSpeedMBs);

                    const currentReadMBs = (bytesRead / (1024 * 1024)) / ((performance.now() - readStart) / 1000);
                    setVal('seq-read-val', currentReadMBs.toFixed(1));
                    setVal('seq-read-peak', `${peakRead.toFixed(1)} MB/s`);
                    updateProgress(`Sequential Read: ${bytesRead / (1024 * 1024)}MB / ${selectedPayloadMB}MB`, 50 + (bytesRead / totalBytes) * 30);
                }
                const totalReadElapsed = (performance.now() - readStart) / 1000;
                const finalReadMBs = (totalBytes / (1024 * 1024)) / Math.max(totalReadElapsed, 0.001);
                lastResult.seqRead = finalReadMBs;
                lastResult.seqReadPeak = peakRead;
                setVal('seq-read-val', finalReadMBs.toFixed(1));

                // ==========================================
                // STAGE 3: 4K Random IOPS & Latency
                // ==========================================
                updateProgress("Testing 4K Random IOPS & Latency...", 85);
                const blockSize = 4096; // 4KB
                const totalOps = 400;
                const blockBuffer = new Uint8Array(blockSize);
                for (let k = 0; k < blockSize; k++) blockBuffer[k] = (k * 17) & 0xFF;

                // 4K Random Write Simulation
                const randWritable = await fileHandle.createWritable({ keepExistingData: true });
                const iopsWriteStart = performance.now();
                let writeLatencies = [];

                for (let op = 0; op < totalOps; op++) {
                    if (abortController.signal.aborted) break;
                    const maxOffset = Math.max(0, totalBytes - blockSize);
                    const randomOffset = Math.floor(Math.random() * (maxOffset / blockSize)) * blockSize;
                    const opStart = performance.now();
                    await randWritable.seek(randomOffset);
                    await randWritable.write(blockBuffer);
                    writeLatencies.push(performance.now() - opStart);
                }
                await randWritable.close();

                const iopsWriteDuration = (performance.now() - iopsWriteStart) / 1000;
                const calcWriteIOPS = Math.round(totalOps / Math.max(iopsWriteDuration, 0.001));
                const avgWriteLatMs = (writeLatencies.reduce((a, b) => a + b, 0) / writeLatencies.length || 0).toFixed(2);
                lastResult.iopsWrite = calcWriteIOPS;
                lastResult.latencyWrite = avgWriteLatMs;
                setVal('iops-write-val', calcWriteIOPS.toLocaleString());
                setVal('latency-write-val', `${avgWriteLatMs} ms`);

                // 4K Random Read
                const iopsReadStart = performance.now();
                let readLatencies = [];
                for (let op = 0; op < totalOps; op++) {
                    if (abortController.signal.aborted) break;
                    const maxOffset = Math.max(0, totalBytes - blockSize);
                    const randomOffset = Math.floor(Math.random() * (maxOffset / blockSize)) * blockSize;
                    const opStart = performance.now();
                    const slice = file.slice(randomOffset, randomOffset + blockSize);
                    await slice.arrayBuffer();
                    readLatencies.push(performance.now() - opStart);
                }
                const iopsReadDuration = (performance.now() - iopsReadStart) / 1000;
                const calcReadIOPS = Math.round(totalOps / Math.max(iopsReadDuration, 0.001));
                const avgReadLatMs = (readLatencies.reduce((a, b) => a + b, 0) / readLatencies.length || 0).toFixed(2);
                lastResult.iopsRead = calcReadIOPS;
                lastResult.latencyRead = avgReadLatMs;
                setVal('iops-read-val', calcReadIOPS.toLocaleString());
                setVal('latency-read-val', `${avgReadLatMs} ms`);

                updateProgress("Benchmark Complete", 100);
                evaluateDriveTier();

            } catch (err) {
                if (err.message === "Benchmark Aborted") {
                    updateProgress("Benchmark Cancelled", 0);
                } else {
                    console.error("Benchmark error:", err);
                    updateProgress(`Error: ${err.message}`, 0);
                }
            } finally {
                // Cleanup temp benchmark file
                if (rootDir && fileHandle) {
                    try {
                        await rootDir.removeEntry(fileName);
                    } catch (cleanupErr) {
                        console.warn("Cleanup notice:", cleanupErr);
                    }
                }
                benchmarkRunning = false;
                if (runBtn) {
                    runBtn.classList.remove('opacity-50', 'pointer-events-none');
                }
                if (cancelBtn) cancelBtn.classList.add('hidden');
                if (runText) runText.innerText = "Run Benchmark Again";
                const engineStatus = document.getElementById('engine-status-val');
                if (engineStatus) engineStatus.innerText = "READY";
            }
        }

        function abortBenchmark() {
            if (abortController) {
                abortController.abort();
            }
        }

        function evaluateDriveTier() {
            const w = lastResult.seqWrite;
            const r = lastResult.seqRead;
            const iops = Math.max(lastResult.iopsWrite, lastResult.iopsRead);

            const titleEl = document.getElementById('drive-tier-title');
            const descEl = document.getElementById('drive-tier-desc');
            let tierTitle = "";
            let tierDesc = "";

            if (r >= 2500 || w >= 2200) {
                tierTitle = "Tier 1: High-Speed PCIe Gen4/5 NVMe SSD";
                tierDesc = "Blazing fast storage throughput. Capable of handling 8K RAW video editing, instant OS boots, and DirectStorage AAA gaming workloads.";
            } else if (r >= 1200 || w >= 1000) {
                tierTitle = "Tier 2: PCIe Gen3 NVMe / Thunderbolt 4 SSD";
                tierDesc = "Excellent high-performance drive. Suitable for heavy professional productivity, code compilation, and fast file transfers.";
            } else if (r >= 400 || w >= 380) {
                tierTitle = "Tier 3: SATA III / USB 3.2 Gen 2 (10Gbps) SSD";
                tierDesc = "Solid everyday solid-state performance. Optimal for typical desktop use, external backups, and console game storage.";
            } else if (r >= 80 || w >= 60) {
                tierTitle = "Tier 4: USB 3.0 Flash Drive / UHS-I MicroSD";
                tierDesc = "Typical portable flash drive performance. Sufficient for casual file transfers and document backups, but limited for running OS installations.";
            } else {
                tierTitle = "Tier 5: Legacy USB 2.0 / Suspect Slow Flash";
                tierDesc = "Very slow throughput. If this is marketed as a modern high-speed SSD or USB 3.0 drive, it may be a counterfeit drive or experiencing severe thermal/cable bottlenecking.";
            }

            lastResult.tier = tierTitle;
            lastResult.timestamp = new Date();
            if (titleEl) titleEl.innerText = tierTitle;
            if (descEl) descEl.innerText = tierDesc;
        }

        function setVal(id, text) {
            const el = document.getElementById(id);
            if (el) el.innerText = text;
        }

        function resetDisplays() {
            setVal('seq-write-val', '0.0');
            setVal('seq-write-peak', '-- MB/s');
            setVal('seq-read-val', '0.0');
            setVal('seq-read-peak', '-- MB/s');
            setVal('iops-write-val', '0');
            setVal('latency-write-val', '-- ms');
            setVal('iops-read-val', '0');
            setVal('latency-read-val', '-- ms');
        }

        function copyBenchmarkReport() {
            if (!lastResult.timestamp) {
                alert("Please run a benchmark first before copying the scorecard.");
                return;
            }
            const report = `=== ToolkitGen SSD & Storage Benchmark ===\n` +
                `Date: ${lastResult.timestamp.toLocaleString()}\n` +
                `Payload Size: ${selectedPayloadMB} MB\n` +
                `Classification: ${lastResult.tier}\n` +
                `Sequential Write: ${lastResult.seqWrite.toFixed(1)} MB/s (Peak: ${lastResult.seqWritePeak.toFixed(1)} MB/s)\n` +
                `Sequential Read: ${lastResult.seqRead.toFixed(1)} MB/s (Peak: ${lastResult.seqReadPeak.toFixed(1)} MB/s)\n` +
                `4K Random Write: ${lastResult.iopsWrite.toLocaleString()} IOPS (${lastResult.latencyWrite} ms latency)\n` +
                `4K Random Read: ${lastResult.iopsRead.toLocaleString()} IOPS (${lastResult.latencyRead} ms latency)\n` +
                `Benchmark URL: https://toolkitgen.com/tool/ssd_speed_benchmark`;

            if (navigator.clipboard) {
                navigator.clipboard.writeText(report).then(() => {
                    const btn = document.getElementById('btn-copy-report');
                    if (btn) {
                        const oldText = btn.innerHTML;
                        btn.innerHTML = 'Scorecard Copied!';
                        setTimeout(() => btn.innerHTML = oldText, 1500);
                    }
                }).catch(() => prompt("Copy your benchmark report:", report));
            } else {
                prompt("Copy your benchmark report:", report);
            }
        }

        function copyToolLink() {
            if (navigator.clipboard) {
                navigator.clipboard.writeText("https://toolkitgen.com/tool/ssd_speed_benchmark").then(() => {
                    alert("Tool link copied to clipboard!");
                }).catch(() => prompt("Copy this link:", "https://toolkitgen.com/tool/ssd_speed_benchmark"));
            } else {
                prompt("Copy this link:", "https://toolkitgen.com/tool/ssd_speed_benchmark");
            }
        }

        function shareBenchmark(platform) {
            const url = encodeURIComponent("https://toolkitgen.com/tool/ssd_speed_benchmark");
            const text = encodeURIComponent(
                lastResult.timestamp 
                    ? `My SSD scored ${lastResult.seqWrite.toFixed(0)} MB/s write and ${lastResult.seqRead.toFixed(0)} MB/s read on ToolkitGen! Check your drive speed:` 
                    : `Benchmark your SSD and NVMe drive speed in real-time online:`
            );
            if (platform === 'wa') window.open(`https://wa.me/?text=${text}%20${url}`, '_blank', 'noopener,noreferrer');
            if (platform === 'tw') window.open(`https://twitter.com/intent/tweet?text=${text}&url=${url}`, '_blank', 'noopener,noreferrer');
        }
